// mdagent: a small agent that edits Markdown files using Claude tool use.
//
// It shows three things:
//  1. Defining tools from typed Go structs (JSON schema generated by reflection).
//  2. Two kinds of tools: "workflow" tools (clarify, plan, exec) that structure
//     the agent's behaviour, and "work" tools (md_*) that touch files.
//  3. The manual agent loop: call the API, run every tool_use block, send all
//     tool_result blocks back in one user message, repeat until end_turn.
//
// Usage:
//
//	export ANTHROPIC_API_KEY=sk-ant-...
//	go run . -dir ./notes "Add a 'Troubleshooting' section to README.md"
package main

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"

	"github.com/anthropics/anthropic-sdk-go"
	"github.com/invopop/jsonschema"
)

// ---------------------------------------------------------------------------
// Generic tool plumbing
// ---------------------------------------------------------------------------

// Tool pairs the definition sent to the API with the Go function that runs it.
type Tool struct {
	Param anthropic.ToolParam
	Run   func(ctx context.Context, raw json.RawMessage) (string, error)
}

// NewTool builds a Tool from a typed input struct. The JSON schema is derived
// from T, and the model's input is decoded into T before fn is called.
//
// Struct tags:
//
//	json:"name"                  -> property name (no omitempty => required)
//	json:"name,omitempty"        -> optional property
//	jsonschema_description:"..." -> description the model sees
//	jsonschema:"enum=a,enum=b"   -> enum values
func NewTool[T any](name, description string, fn func(ctx context.Context, in T) (string, error)) Tool {
	r := jsonschema.Reflector{AllowAdditionalProperties: false, DoNotReference: true}
	var zero T
	schema := r.Reflect(&zero)

	return Tool{
		Param: anthropic.ToolParam{
			Name:        name,
			Description: anthropic.String(description),
			InputSchema: anthropic.ToolInputSchemaParam{
				Properties: schema.Properties,
				Required:   schema.Required,
			},
		},
		Run: func(ctx context.Context, raw json.RawMessage) (string, error) {
			var in T
			if err := json.Unmarshal(raw, &in); err != nil {
				return "", fmt.Errorf("invalid input for %s: %w", name, err)
			}
			return fn(ctx, in)
		},
	}
}

// ---------------------------------------------------------------------------
// Agent state shared by the workflow tools
// ---------------------------------------------------------------------------

type Step struct {
	ID     int    `json:"id"`
	Title  string `json:"title"`
	Status string `json:"status"` // pending | in_progress | done | failed
	Note   string `json:"note,omitempty"`
}

type Agent struct {
	root  string // all file access is confined to this directory
	plan  []Step
	stdin *bufio.Reader
}

// safePath resolves a model-supplied path inside a.root and rejects escapes
// like "../../etc/passwd" and non-.md files.
func (a *Agent) safePath(p string) (string, error) {
	if !strings.EqualFold(filepath.Ext(p), ".md") {
		return "", fmt.Errorf("only .md files are allowed, got %q", p)
	}
	full := filepath.Join(a.root, filepath.Clean("/"+p))
	rel, err := filepath.Rel(a.root, full)
	if err != nil || strings.HasPrefix(rel, "..") {
		return "", fmt.Errorf("path %q is outside the workspace", p)
	}
	return full, nil
}

// ---------------------------------------------------------------------------
// Workflow tools: clarify, plan, exec
// ---------------------------------------------------------------------------

type ClarifyInput struct {
	Question string   `json:"question" jsonschema_description:"One specific question for the user. Ask only when the request is ambiguous and a wrong guess would be costly."`
	Options  []string `json:"options,omitempty" jsonschema_description:"Optional suggested answers the user can pick from."`
}

type PlanInput struct {
	Steps []string `json:"steps" jsonschema_description:"Ordered, concrete steps. Each step should map to one or a few md_* tool calls."`
}

type ExecInput struct {
	StepID int    `json:"step_id" jsonschema_description:"ID of the plan step, as returned by the plan tool."`
	Status string `json:"status" jsonschema:"enum=in_progress,enum=done,enum=failed" jsonschema_description:"New status of the step."`
	Note   string `json:"note,omitempty" jsonschema_description:"Short note on what was done or why it failed."`
}

func (a *Agent) clarify(_ context.Context, in ClarifyInput) (string, error) {
	fmt.Printf("\n❓ %s\n", in.Question)
	for i, o := range in.Options {
		fmt.Printf("   %d) %s\n", i+1, o)
	}
	fmt.Print("> ")
	answer, err := a.stdin.ReadString('\n')
	if err != nil && !errors.Is(err, os.ErrClosed) && answer == "" {
		return "", fmt.Errorf("could not read answer: %w", err)
	}
	answer = strings.TrimSpace(answer)
	// Let the user answer "2" instead of retyping an option.
	var n int
	if _, err := fmt.Sscanf(answer, "%d", &n); err == nil && n >= 1 && n <= len(in.Options) {
		answer = in.Options[n-1]
	}
	if answer == "" {
		return "User gave no answer. Proceed with the most reasonable assumption and state it.", nil
	}
	return "User answered: " + answer, nil
}

func (a *Agent) makePlan(_ context.Context, in PlanInput) (string, error) {
	if len(in.Steps) == 0 {
		return "", errors.New("plan must have at least one step")
	}
	a.plan = a.plan[:0]
	fmt.Println("\n📋 Plan:")
	for i, s := range in.Steps {
		a.plan = append(a.plan, Step{ID: i + 1, Title: s, Status: "pending"})
		fmt.Printf("   %d. %s\n", i+1, s)
	}
	out, _ := json.Marshal(a.plan)
	return "Plan recorded. Execute steps in order and report each with the exec tool.\n" + string(out), nil
}

func (a *Agent) exec(_ context.Context, in ExecInput) (string, error) {
	if len(a.plan) == 0 {
		return "", errors.New("no plan yet: call the plan tool first")
	}
	if in.StepID < 1 || in.StepID > len(a.plan) {
		return "", fmt.Errorf("unknown step_id %d (plan has %d steps)", in.StepID, len(a.plan))
	}
	// Enforce ordering: earlier steps must be finished first.
	for _, s := range a.plan[:in.StepID-1] {
		if s.Status != "done" && s.Status != "failed" {
			return "", fmt.Errorf("step %d (%q) is not finished yet", s.ID, s.Title)
		}
	}
	s := &a.plan[in.StepID-1]
	s.Status, s.Note = in.Status, in.Note
	icon := map[string]string{"in_progress": "▶", "done": "✅", "failed": "❌"}[in.Status]
	fmt.Printf("%s step %d: %s %s\n", icon, s.ID, s.Title, in.Note)

	remaining := 0
	for _, s := range a.plan {
		if s.Status == "pending" || s.Status == "in_progress" {
			remaining++
		}
	}
	return fmt.Sprintf("Step %d is now %s. %d step(s) remaining.", s.ID, s.Status, remaining), nil
}

// ---------------------------------------------------------------------------
// Markdown tools
// ---------------------------------------------------------------------------

type PathInput struct {
	Path string `json:"path" jsonschema_description:"Path to a .md file, relative to the workspace root."`
}

type WriteInput struct {
	Path    string `json:"path" jsonschema_description:"Path to a .md file, relative to the workspace root."`
	Content string `json:"content" jsonschema_description:"Full Markdown content. Overwrites the file."`
}

type SectionInput struct {
	Path    string `json:"path" jsonschema_description:"Path to a .md file, relative to the workspace root."`
	Heading string `json:"heading" jsonschema_description:"Exact heading text without the leading #'s, e.g. 'Installation'."`
	Content string `json:"content" jsonschema_description:"New body for the section (without the heading line)."`
	Level   int    `json:"level,omitempty" jsonschema_description:"Heading level 1-6 used if the section must be created. Default 2."`
}

func (a *Agent) mdList(_ context.Context, _ struct{}) (string, error) {
	var files []string
	err := filepath.WalkDir(a.root, func(p string, d os.DirEntry, err error) error {
		if err == nil && !d.IsDir() && strings.EqualFold(filepath.Ext(p), ".md") {
			rel, _ := filepath.Rel(a.root, p)
			files = append(files, rel)
		}
		return err
	})
	if len(files) == 0 {
		return "No Markdown files in the workspace.", err
	}
	return strings.Join(files, "\n"), err
}

func (a *Agent) mdRead(_ context.Context, in PathInput) (string, error) {
	p, err := a.safePath(in.Path)
	if err != nil {
		return "", err
	}
	b, err := os.ReadFile(p)
	if err != nil {
		return "", err
	}
	// Prefix line numbers so the model can refer to exact locations.
	lines := strings.Split(string(b), "\n")
	var sb strings.Builder
	for i, l := range lines {
		fmt.Fprintf(&sb, "%4d| %s\n", i+1, l)
	}
	return sb.String(), nil
}

func (a *Agent) mdOutline(_ context.Context, in PathInput) (string, error) {
	p, err := a.safePath(in.Path)
	if err != nil {
		return "", err
	}
	b, err := os.ReadFile(p)
	if err != nil {
		return "", err
	}
	var sb strings.Builder
	for _, h := range headings(strings.Split(string(b), "\n")) {
		fmt.Fprintf(&sb, "%s%s (line %d)\n", strings.Repeat("  ", h.Level-1), h.Title, h.Line+1)
	}
	if sb.Len() == 0 {
		return "No headings found.", nil
	}
	return sb.String(), nil
}

func (a *Agent) mdWrite(_ context.Context, in WriteInput) (string, error) {
	p, err := a.safePath(in.Path)
	if err != nil {
		return "", err
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		return "", err
	}
	if err := os.WriteFile(p, []byte(in.Content), 0o644); err != nil {
		return "", err
	}
	return fmt.Sprintf("Wrote %d bytes to %s.", len(in.Content), in.Path), nil
}

// mdUpsertSection replaces the body of a section (up to the next heading of the
// same or higher level), or appends a new section if the heading is missing.
func (a *Agent) mdUpsertSection(_ context.Context, in SectionInput) (string, error) {
	p, err := a.safePath(in.Path)
	if err != nil {
		return "", err
	}
	b, err := os.ReadFile(p)
	if err != nil && !os.IsNotExist(err) {
		return "", err
	}
	var lines []string
	if t := strings.TrimRight(string(b), "\n"); t != "" {
		lines = strings.Split(t, "\n")
	}
	body := strings.Split(strings.TrimRight(in.Content, "\n"), "\n")

	hs := headings(lines)
	start, level, end := -1, 0, len(lines)
	for i, h := range hs {
		if start == -1 && strings.EqualFold(h.Title, in.Heading) {
			start, level = h.Line, h.Level
			for _, next := range hs[i+1:] {
				if next.Level <= level {
					end = next.Line
					break
				}
			}
		}
	}

	var out []string
	var verb string
	if start == -1 {
		if in.Level < 1 || in.Level > 6 {
			in.Level = 2
		}
		out = lines
		if len(out) > 0 {
			out = append(out, "")
		}
		out = append(out, strings.Repeat("#", in.Level)+" "+in.Heading, "")
		out = append(out, body...)
		verb = "Appended new"
	} else {
		out = append(out, lines[:start+1]...)
		out = append(out, "")
		out = append(out, body...)
		if end < len(lines) {
			out = append(out, "")
			out = append(out, lines[end:]...)
		}
		verb = "Replaced"
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		return "", err
	}
	if err := os.WriteFile(p, []byte(strings.Join(out, "\n")+"\n"), 0o644); err != nil {
		return "", err
	}
	return fmt.Sprintf("%s section %q in %s.", verb, in.Heading, in.Path), nil
}

type heading struct {
	Line, Level int
	Title       string
}

// headings returns ATX headings, skipping lines inside ``` or ~~~ code fences
// (a "# comment" in a shell snippet is not a heading).
func headings(lines []string) []heading {
	var hs []heading
	fence := ""
	for i, l := range lines {
		t := strings.TrimSpace(l)
		if fence == "" && (strings.HasPrefix(t, "```") || strings.HasPrefix(t, "~~~")) {
			fence = t[:3]
			continue
		}
		if fence != "" {
			if strings.HasPrefix(t, fence) {
				fence = ""
			}
			continue
		}
		if lvl, title, ok := parseHeading(l); ok {
			hs = append(hs, heading{Line: i, Level: lvl, Title: title})
		}
	}
	return hs
}

func parseHeading(line string) (level int, title string, ok bool) {
	t := strings.TrimLeft(line, " ")
	for level < len(t) && level < 7 && t[level] == '#' {
		level++
	}
	if level == 0 || level > 6 || (len(t) > level && t[level] != ' ') {
		return 0, "", false
	}
	return level, strings.TrimSpace(strings.TrimRight(t[level:], "# ")), true
}

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------

const systemPrompt = `You edit Markdown files in a local workspace.

Workflow:
1. If the request is ambiguous in a way that changes the result, call clarify (at most twice). Otherwise don't.
2. Call plan once with concrete steps.
3. For each step: exec(step_id, "in_progress"), do the work with md_* tools, then exec(step_id, "done" or "failed").
4. Read a file (md_outline or md_read) before changing it.
5. Finish with a two-sentence summary of what changed.`

func (a *Agent) tools() []Tool {
	return []Tool{
		NewTool("clarify", "Ask the user a clarifying question and wait for the answer.", a.clarify),
		NewTool("plan", "Record the ordered plan of steps you will execute. Replaces any previous plan.", a.makePlan),
		NewTool("exec", "Update the status of a plan step. Call before starting a step and after finishing it.", a.exec),
		NewTool("md_list", "List all Markdown files in the workspace.", a.mdList),
		NewTool("md_read", "Read a Markdown file with line numbers.", a.mdRead),
		NewTool("md_outline", "Return the heading outline of a Markdown file (cheaper than md_read).", a.mdOutline),
		NewTool("md_write", "Create or fully overwrite a Markdown file.", a.mdWrite),
		NewTool("md_upsert_section", "Replace the body of a section by heading, or append it if missing.", a.mdUpsertSection),
	}
}

func (a *Agent) Run(ctx context.Context, client anthropic.Client, task string) error {
	tools := a.tools()
	byName := make(map[string]Tool, len(tools))
	params := make([]anthropic.ToolUnionParam, 0, len(tools))
	for _, t := range tools {
		byName[t.Param.Name] = t
		p := t.Param // copy: the union holds a pointer
		params = append(params, anthropic.ToolUnionParam{OfTool: &p})
	}

	messages := []anthropic.MessageParam{
		anthropic.NewUserMessage(anthropic.NewTextBlock(task)),
	}

	for turn := 0; turn < 30; turn++ { // hard cap so a confused model can't loop forever
		msg, err := client.Messages.New(ctx, anthropic.MessageNewParams{
			Model:     anthropic.ModelClaudeSonnet5_5,
			MaxTokens: 8192,
			System:    []anthropic.TextBlockParam{{Text: systemPrompt}},
			Tools:     params,
			Messages:  messages,
		})
		if err != nil {
			return err
		}
		// The assistant turn (text + tool_use blocks) must go back verbatim.
		messages = append(messages, msg.ToParam())

		var results []anthropic.ContentBlockParamUnion
		for _, block := range msg.Content {
			switch b := block.AsAny().(type) {
			case anthropic.TextBlock:
				fmt.Println("\n🤖", b.Text)
			case anthropic.ToolUseBlock:
				out, isErr := a.call(ctx, byName, b)
				results = append(results, anthropic.NewToolResultBlock(b.ID, out, isErr))
			}
		}

		if msg.StopReason != anthropic.StopReasonToolUse {
			return nil // end_turn, max_tokens, etc.
		}
		// Every tool_use needs a tool_result, all in ONE user message.
		messages = append(messages, anthropic.NewUserMessage(results...))
	}
	return errors.New("stopped after 30 turns")
}

// call runs one tool. Errors are returned to the model (is_error=true) rather
// than aborting, so it can recover — e.g. read the file it forgot to read.
func (a *Agent) call(ctx context.Context, byName map[string]Tool, b anthropic.ToolUseBlock) (string, bool) {
	t, ok := byName[b.Name]
	if !ok {
		return "unknown tool " + b.Name, true
	}
	if !strings.HasPrefix(b.Name, "exec") && b.Name != "plan" && b.Name != "clarify" {
		fmt.Printf("   🔧 %s %s\n", b.Name, truncate(string(b.Input), 120))
	}
	out, err := t.Run(ctx, b.Input)
	if err != nil {
		fmt.Printf("   ⚠️  %v\n", err)
		return err.Error(), true
	}
	return out, false
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "…"
}

func main() {
	dir := flag.String("dir", ".", "workspace directory containing Markdown files")
	flag.Parse()
	task := strings.Join(flag.Args(), " ")
	if task == "" {
		log.Fatal(`usage: mdagent -dir ./notes "what to do"`)
	}
	root, err := filepath.Abs(*dir)
	if err != nil {
		log.Fatal(err)
	}

	client := anthropic.NewClient() // reads ANTHROPIC_API_KEY
	agent := &Agent{root: root, stdin: bufio.NewReader(os.Stdin)}
	if err := agent.Run(context.Background(), client, task); err != nil {
		log.Fatal(err)
	}
}
